python3 -c "from pathlib import Path; p=Path('programs/task-a21f0ce7.py'); p.parent.mkdir(exist_ok=True); p.write_text('def transform(grid):
    # Combine the four separated motifs by cellwise XOR, aligned at their top-left bounds.
    H,W=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if grid[r][c] and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); pts=[]
                while st:
                    y,x=st.pop(); pts.append((y,x))
                    for q in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0<=q[0]<H and 0<=q[1]<W and grid[q[0]][q[1]] and q not in seen: seen.add(q); st.append(q)
                comps.append(pts)
    boxes=[]
    for pts in comps:
        a=min(y for y,x in pts); b=min(x for y,x in pts); z=max(y for y,x in pts); w=max(x for y,x in pts)
        boxes.append((a,b,z,w,{(y-a,x-b) for y,x in pts}))
    if not boxes: return [[0]]
    h=max(z-a+1 for a,b,z,w,s in boxes); w=max(x-b+1 for a,b,z,x,s in boxes); out=[[0]*w for _ in range(h)]
    for a,b,z,x,s in boxes:
        for y,t in s: out[y][t]=0 if out[y][t] else grid[a+y][b+t]
    return out
')"

